  "required": [
    "prompt"
  ]
}

{
  "type": "object",
  "properties": {
    "prompt": {
      "type": "string",
      "description": "text prompt describing the video to generate"
    },
    "size": {
      "type": "string",
      "description": "video size, e.g. 1920x1080"
    },
    "quality": {
      "type": "string",
      "description": "video quality, e.g. standard or high"
